def parse_env(text, defaults=None):
    """Parse environment-style assignments, overlaying them on defaults.

    Parsing is deliberately independent of the process environment. Errors
    include the physical line number so callers can add file context.
    """
    result = {} if defaults is None else dict(defaults)

    for line_number, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue

        if line.startswith('export') and (len(line) == 6 or line[6].isspace()):
            line = line[6:].lstrip()

        if '=' not in line:
            raise ValueError(f"invalid assignment on line {line_number}")
        key, value = line.split('=', 1)
        key = key.strip()
        if not key or any(char.isspace() for char in key):
            raise ValueError(f"invalid key on line {line_number}")

        value = value.strip()
        if value.startswith(('\"', "'")):
            quote = value[0]
            end = value.find(quote, 1)
            if end < 0 or value[end + 1:].strip() and not value[end + 1:].lstrip().startswith('#'):
                raise ValueError(f"invalid quoted value on line {line_number}")
            value = value[1:end]
        else:
            value = value.split('#', 1)[0].rstrip()

        result[key] = value

    return result

